-- Checked 2 Nov 2026 against each syllabus PDF on cambridgeinternational.org ("Assessment overview",
-- "Before you start" for exam series, specimen papers listed on the subject pages). Versions before the ones
-- Cambridge still lists are not checked: they copy the papers of the next version, with a note on each row.

-- Components marked by the school (coursework, speaking) have no question paper: shown, never asked for.
ALTER TABLE syllabus_paper ADD COLUMN school_assessed INTEGER NOT NULL DEFAULT 0 CHECK (school_assessed IN (0, 1));

